/*
 * One-time generator for tests/fixtures/m6-saves. Run ONLY against the M6 signed-off
 * product code (631c131 tree); the committed files are the M7 compatibility oracle and
 * must never be regenerated by M7 code. Uses the normal seed-42 cannon command route.
 */
const fs = require('node:fs');
const path = require('node:path');
const zlib = require('node:zlib');

const OUT = path.resolve(__dirname, '../tests/fixtures/m6-saves');
const RUN_ID = 'm6-fixture-cannon-seed42';
const CREATED_AT = '2026-10-06T00:00:00.000Z';

(async () => {
  const { createServer } = await import('vite');
  const server = await createServer({ root: path.resolve(__dirname, '..'), server: { middlewareMode: true, ws: false }, optimizeDeps: { noDiscovery: true, include: [] }, appType: 'custom' });
  try {
    const api = await server.ssrLoadModule('/src/simulation/match.ts');
    const { BattleHistory, validateBattleCollection } = await server.ssrLoadModule('/src/replay/index.ts');
    const { validateEnvelope } = await server.ssrLoadModule('/src/persistence/format.ts');
    const { run } = require('./generate-m5-route.cjs');
    const history = new BattleHistory(RUN_ID);
    const envelope = match => ({ kind: 'hex-autobattler-save', saveFormatVersion: 1, replayFormatVersion: 1, runId: RUN_ID, createdAt: CREATED_AT,
      match: structuredClone(match), battles: structuredClone(history.completedRecords), currentBattle: structuredClone(history.capturePrefix()) });
    const saves = {};
    const take = (name, match) => { if (!saves[name]) saves[name] = envelope(match); };
    const combatEvents = events => events.filter(event => event.domain === 'combat');
    let first = true;
    const route = await run(api, { build: 'cannon', seed: 42, onStep: (before, result, command) => {
      if (first) { first = false; take('01-initial-component-choice', before); }
      history.observe({ before, after: result.state, events: combatEvents(result.events), reason: command ? 'command' : 'tick' });
      const after = result.state, done = history.completedRecords.length;
      if (after.phase === 'preparation') take('02-preparation', after);
      if (after.phase === 'choice' && after.pendingChoice?.kind === 'augment') take('03-augment-choice', after);
      if (after.phase === 'combat' && after.combat?.tick === 40 && done >= 2) take('04-combat-tick40-with-history', after);
      if (after.phase === 'settlement' && done >= 3) take('05-settlement', after);
      if (after.phase === 'choice' && after.pendingChoice?.kind === 'anomaly' && after.pendingChoice.step === 'offer') take('06-anomaly-offer', after);
    } });
    take('07-game-over', route.final);
    fs.mkdirSync(OUT, { recursive: true });
    const manifest = [];
    for (const [name, save] of Object.entries(saves)) {
      await validateEnvelope(structuredClone(save), validateBattleCollection);
      const text = JSON.stringify(save);
      fs.writeFileSync(path.join(OUT, `${name}.json.gz`), zlib.gzipSync(text, { level: 9 }));
      manifest.push({ file: `${name}.json.gz`, jsonBytes: Buffer.byteLength(text), phase: save.match.phase, round: save.match.round,
        battles: save.battles.length, currentBattleTick: save.currentBattle?.endTick ?? null });
    }
    fs.writeFileSync(path.join(OUT, 'manifest.json'), JSON.stringify({ generatedFrom: 'M6 signed-off product code (631c131 tree)', route: 'cannon seed 42', saves: manifest }, null, 2) + '\n');
    console.log(manifest);
  } finally { await server.close(); }
})().catch(error => { console.error(error); process.exitCode = 1; });
